#!/usr/bin/env python3
import csv
import re
import sys
import urllib.parse
import zipfile


def parse_attrs(field):
    attrs = {}
    for part in field.strip().split(";"):
        if not part or "=" not in part:
            continue
        key, value = part.split("=", 1)
        attrs[key] = urllib.parse.unquote(value)
    return attrs


def main():
    marker_path, ncbi_zip_path, out_path = sys.argv[1:4]
    marker_rows = []
    targets = set()
    with open(marker_path, newline="") as fh:
        reader = csv.DictReader(fh, delimiter="\t")
        for row in reader:
            marker_rows.append(row)
            targets.add(row["gene"])

    annotations = {
        gene: {"symbols": set(), "products": set(), "notes": set(), "features": set()}
        for gene in targets
    }
    id_pat = re.compile(r"(BLAG[0-9]+)_[0-9]+")
    with zipfile.ZipFile(ncbi_zip_path) as zf:
        gff_name = next(name for name in zf.namelist() if name.endswith("/genomic.gff"))
        with zf.open(gff_name) as raw:
            for bline in raw:
                if b"BLAG" not in bline:
                    continue
                line = bline.decode("utf-8", "replace").rstrip("\n")
                fields = line.split("\t")
                if len(fields) != 9:
                    continue
                found = {m.group(1) for m in id_pat.finditer(fields[8])}
                found &= targets
                if not found:
                    continue
                attrs = parse_attrs(fields[8])
                for gene in found:
                    ann = annotations[gene]
                    ann["features"].add(fields[2])
                    for key in ("gene", "Name"):
                        if attrs.get(key):
                            ann["symbols"].add(attrs[key])
                    if attrs.get("product"):
                        ann["products"].add(attrs["product"])
                    if attrs.get("Note"):
                        ann["notes"].add(attrs["Note"])

    with open(out_path, "w", newline="") as out:
        fieldnames = list(marker_rows[0].keys()) + [
            "annotation_symbols",
            "annotation_products",
            "annotation_notes",
            "annotation_features",
        ]
        writer = csv.DictWriter(out, fieldnames=fieldnames, delimiter="\t")
        writer.writeheader()
        for row in marker_rows:
            ann = annotations[row["gene"]]
            row = dict(row)
            row["annotation_symbols"] = "|".join(sorted(ann["symbols"]))
            row["annotation_products"] = "|".join(sorted(ann["products"]))
            row["annotation_notes"] = "|".join(sorted(ann["notes"]))[:500]
            row["annotation_features"] = "|".join(sorted(ann["features"]))
            writer.writerow(row)


if __name__ == "__main__":
    main()

